// Shared realtime types + small mapping helpers used across providers.

import type { AgentState } from "@/components/ui/orb";
import type { AgentState as BarState } from "@/components/ui/bar-visualizer";

export type CallState = "idle" | "connecting" | "listening" | "speaking" | "interrupted" | "ended";

export interface SessionTurn {
  id: string;
  who: "agent" | "user";
  text: string;
  live?: boolean;
}

// The unified surface every provider exposes to the UI. The UI never talks to a
// provider directly — it binds to this, and the active provider is swapped
// behind it (mock for the design's fake lifecycle, ElevenLabs for the real one).
export interface SessionApi {
  callState: CallState;
  turns: SessionTurn[];
  caption: string;
  muted: boolean;
  elapsed: number;
  isReal: boolean;
  toggleMute: () => void;
  start: () => void;
  hangup: () => void;
  interrupt: () => void;
  /** End the user's turn now (half-duplex cascade STT). No-op on full-duplex engines. */
  sendTurn: () => void;
  /** Whether this engine has a manual end-of-turn (only the cascade STT does). */
  canSendTurn: boolean;
  /** Whether the manual end-of-turn is currently usable while capture remains active. */
  sendTurnEnabled: boolean;
  getInputVolume: () => number;
  getOutputVolume: () => number;
}

export function isLive(s: CallState): boolean {
  return s !== "idle" && s !== "ended";
}

// CallState → ElevenLabs WebGL Orb agentState.
export function toOrbState(s: CallState): AgentState {
  switch (s) {
    case "speaking":
      return "talking";
    case "listening":
    case "interrupted":
      return "listening";
    case "connecting":
      return "thinking";
    default:
      return null;
  }
}

// CallState → BarVisualizer state.
export function toBarState(s: CallState): BarState {
  switch (s) {
    case "speaking":
      return "speaking";
    case "connecting":
      return "connecting";
    case "interrupted":
    case "listening":
      return "listening";
    default:
      return "initializing";
  }
}
// Mints a short-lived xAI realtime client-secret (ephemeral token) server-side
// so the browser can open a WebSocket to xAI WITHOUT ever seeing XAI_API_KEY.
//
// Flow: client POSTs here → we call xAI with the secret key → return the
// ephemeral token JSON. The browser then connects with
//   new WebSocket(".../v1/realtime?model=…", ["xai-client-secret." + token]).
//
// Dev only: XAI_API_KEY is provided via fnox (`fnox exec -- bun run dev`).

export const runtime = "nodejs";
// Never cache a freshly-minted secret.
export const dynamic = "force-dynamic";

const CLIENT_SECRETS_URL = "https://api.x.ai/v1/realtime/client_secrets";
const TOKEN_TTL_SECONDS = 300;

export async function POST(): Promise<Response> {
  const apiKey = process.env.XAI_API_KEY;
  if (!apiKey) {
    // Do not echo any key material; just say it's unset.
    return Response.json(
      { error: "XAI_API_KEY is not set on the server (provide it via fnox)." },
      { status: 500 },
    );
  }

  let upstream: Response;
  try {
    upstream = await fetch(CLIENT_SECRETS_URL, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ expires_after: { seconds: TOKEN_TTL_SECONDS } }),
    });
  } catch (err) {
    return Response.json(
      { error: `Failed to reach xAI: ${err instanceof Error ? err.message : "network error"}` },
      { status: 502 },
    );
  }

  const text = await upstream.text();
  if (!upstream.ok) {
    // Surface xAI's status + body (it doesn't contain our key) for debugging.
    return Response.json(
      { error: "xAI client_secrets request failed", status: upstream.status, detail: text },
      { status: 502 },
    );
  }

  // Pass the token JSON straight through; the client extracts the value defensively.
  return new Response(text, {
    status: 200,
    headers: { "Content-Type": "application/json", "Cache-Control": "no-store" },
  });
}
