// Probe mem0 v3 REST with a throwaway user: add → wait → search → get-all → delete.
const BASE = "https://api.mem0.ai";
const headers = {
  Authorization: `Token ${process.env.MEM0_API_KEY ?? ""}`,
  "Content-Type": "application/json",
};
const USER = `tsubaki-probe-${Date.now()}`;

async function call(method: string, path: string, body?: unknown) {
  const res = await fetch(BASE + path, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  console.log(method, path, res.status, text.slice(0, 700));
  return text ? JSON.parse(text) : null;
}

await call("POST", "/v3/memories/add/", {
  user_id: USER,
  messages: [
    { role: "assistant", content: "Good evening. What brings you to the garden?" },
    { role: "user", content: "I'm Ren. I just moved to Kyoto and I play cello in a small quartet." },
    { role: "assistant", content: "A cellist in Kyoto. The river must suit you." },
    { role: "user", content: "ok cool, thanks, bye" },
  ],
  metadata: { persona: "vesper", lang: "en", source: "elevenlabs", conversation_id: "conv_probe" },
});

for (let i = 0; i < 8; i++) {
  await new Promise((r) => setTimeout(r, 4000));
  const all = await call("POST", "/v3/memories/", { filters: { user_id: USER } });
  if ((all?.results ?? []).length > 0) break;
}

await call("POST", "/v3/memories/search/", {
  query: "who the user is, their life, preferences and what we talked about before",
  filters: { user_id: USER },
  top_k: 10,
});

await call("DELETE", `/v1/memories/?user_id=${USER}`);

