// End-to-end probe of /api/memory/* against the running dev server, with a throwaway visitor.
import { formatMemoryUpdate } from "../../../../../../../Users/jessearmand/Develop/realtime-persona/lib/memory/framing";

const APP = "http://localhost:3000";
const USER = `tsubaki-${crypto.randomUUID()}`;
const mem0 = (path: string, init: RequestInit = {}) =>
  fetch("https://api.mem0.ai" + path, {
    ...init,
    headers: {
      Authorization: `Token ${process.env.MEM0_API_KEY ?? ""}`,
      "Content-Type": "application/json",
    },
  });

async function post(path: string, body: unknown) {
  const res = await fetch(APP + path, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  const text = await res.text();
  console.log(path, res.status, text.slice(0, 400));
  return { status: res.status, json: text ? JSON.parse(text) : null };
}

// 1. Validation.
await post("/api/memory/recall", { userId: "alice@example.com" });
await post("/api/memory/ingest", { userId: USER, conversationId: "../../v1/user" });

// 2. Fresh visitor: nothing remembered.
await post("/api/memory/recall", { userId: USER });

// 3. Ownership: a real stored conversation that isn't this visitor's.
const list = await fetch("https://api.elevenlabs.io/v1/convai/conversations?page_size=1", {
  headers: { "xi-api-key": process.env.ELEVENLABS_API_KEY ?? "" },
});
const conv = ((await list.json()).conversations ?? [])[0];
if (conv) {
  await post("/api/memory/ingest", {
    userId: USER,
    conversationId: conv.conversation_id,
    persona: "vesper",
    lang: "en",
  });
}

// 4. Seed mem0 for this visitor, then recall through the app.
await mem0("/v3/memories/add/", {
  method: "POST",
  body: JSON.stringify({
    user_id: USER,
    messages: [
      { role: "user", content: "My name is Ren and I play cello. I'm nervous about a concert on Friday." },
      { role: "assistant", content: "A concert on Friday. The bow will steady in your hand." },
    ],
    metadata: { source: "probe" },
  }),
});
let memories: string[] = [];
for (let i = 0; i < 10 && memories.length === 0; i++) {
  await new Promise((r) => setTimeout(r, 4000));
  memories = (await post("/api/memory/recall", { userId: USER })).json?.memories ?? [];
}
console.log("\n--- EN update ---\n" + formatMemoryUpdate(memories, "en"));
console.log("\n--- JA update ---\n" + formatMemoryUpdate(memories, "ja"));

// 5. Clean up the throwaway visitor.
const del = await mem0(`/v1/memories/?user_id=${USER}`, { method: "DELETE" });
console.log("\ncleanup", del.status);

