// Success-path probe: a real (text-turn) ElevenLabs conversation with a userId and a
// contextual update, then the app's ingest and recall routes. Cleans up after itself.
const AGENT = "agent_5701kzp5dn4me4nt5vk1ya61kf48"; // tsubaki-vesper (EN), public
const APP = "http://localhost:3000";
const USER = `tsubaki-${crypto.randomUUID()}`;
const XI = { "xi-api-key": process.env.ELEVENLABS_API_KEY ?? "" };
const CONV_URL = "https://api.elevenlabs.io/v1/convai/conversations";
const MARKER = "PROBE-CONTEXT-MARKER: the visitor likes winter persimmons.";
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

// ── 1. Converse ────────────────────────────────────────────────────────────
const conversationId = await new Promise<string>((resolve, reject) => {
  const ws = new WebSocket(`wss://api.elevenlabs.io/v1/convai/conversation?agent_id=${AGENT}`);
  let id = "";
  let agentReplies = 0;
  const timer = setTimeout(() => (ws.close(), id ? resolve(id) : reject(new Error("timeout"))), 45_000);
  ws.onopen = () =>
    ws.send(JSON.stringify({ type: "conversation_initiation_client_data", user_id: USER }));
  ws.onmessage = (ev) => {
    const msg = JSON.parse(String(ev.data));
    if (msg.type === "ping") {
      ws.send(JSON.stringify({ type: "pong", event_id: msg.ping_event?.event_id }));
    } else if (msg.type === "conversation_initiation_metadata") {
      id = msg.conversation_initiation_metadata_event.conversation_id;
      console.log("connected", id);
      ws.send(JSON.stringify({ type: "contextual_update", text: MARKER }));
    } else if (msg.type === "agent_response") {
      agentReplies++;
      console.log("agent:", msg.agent_response_event?.agent_response);
      if (agentReplies === 1) {
        ws.send(
          JSON.stringify({
            type: "user_message",
            text: "My name is Ren. I play cello in a quartet, and I just moved to Kyoto.",
          }),
        );
      } else {
        clearTimeout(timer);
        ws.close();
        resolve(id);
      }
    }
  };
  ws.onerror = () => reject(new Error("ws error"));
});

// ── 2. What a GET returns right after close, then the finished record ──────
const first = await fetch(`${CONV_URL}/${conversationId}`, { headers: XI });
console.log("\nGET right after close:", first.status, first.ok ? (await first.json()).status : "");
let detail: Record<string, any> = {};
for (let i = 0; i < 30; i++) {
  const res = await fetch(`${CONV_URL}/${conversationId}`, { headers: XI });
  if (res.ok) {
    detail = await res.json();
    if (detail.status === "done" || detail.status === "failed") break;
  }
  await sleep(3000);
}
console.log("final status:", detail.status, "| user_id matches:", detail.user_id === USER);
console.log("initiator_id:", detail.metadata?.initiator_id);
for (const t of detail.transcript ?? []) {
  console.log(
    `  [${t.role}] ${String(t.message ?? "").slice(0, 90)} | contextual_update_info=${JSON.stringify(t.contextual_update_info)?.slice(0, 120)}`,
  );
}

// ── 3. Ingest through the app, then recall ─────────────────────────────────
const ingest = await fetch(`${APP}/api/memory/ingest`, {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ userId: USER, conversationId, persona: "vesper", lang: "en" }),
});
console.log("\ningest:", ingest.status, await ingest.text());
let memories: string[] = [];
for (let i = 0; i < 12 && memories.length === 0; i++) {
  await sleep(4000);
  const r = await fetch(`${APP}/api/memory/recall`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ userId: USER }),
  });
  memories = ((await r.json()).memories ?? []) as string[];
}
console.log("recalled:", memories);
console.log("marker leaked into memory:", memories.some((m) => /persimmon|PROBE/i.test(m)));

// ── 4. Clean up ────────────────────────────────────────────────────────────
const m0 = await fetch(`https://api.mem0.ai/v1/memories/?user_id=${USER}`, {
  method: "DELETE",
  headers: { Authorization: `Token ${process.env.MEM0_API_KEY ?? ""}` },
});
const el = await fetch(`${CONV_URL}/${conversationId}`, { method: "DELETE", headers: XI });
console.log("\ncleanup mem0:", m0.status, "| elevenlabs conversation:", el.status);

