"use client";

// Long-term memory for ElevenLabs calls (mem0), as three lifecycle hooks:
//
//   begin(persona, lang)    CALL pressed: start recall in parallel with connecting,
//                           so memory never delays the call. Returns the userId
//                           to pass to startSession.
//   connected(id, send)     onConnect: open the conversation, then send the
//                           recalled memories as a contextual update.
//   ended()                 onDisconnect: ingest the oldest open conversation.
//
// The SDK's connect/disconnect callbacks carry no attempt, and on a language
// change the old session's onDisconnect can land after begin() has armed the
// new call. So the hook never ends "the current call". Each onConnect opens a
// conversation, and each onDisconnect retires the oldest open one: sessions on
// this one SDK hook close in the order they opened. A late disconnect therefore
// ingests the old call and leaves the new one alone.
//
// begin() also takes an attempt token, so a recall from a replaced call never
// reaches the new one. Each conversation ingests at most once.

import { useCallback, useMemo, useRef } from "react";
import type { Lang } from "@/lib/lang";
import { ingestConversation, recallMemories } from "./client";
import { formatMemoryUpdate } from "./framing";
import { getMemoryUserId } from "./user-id";

interface CallRecord {
  attempt: number;
  userId: string;
  persona?: string;
  lang: Lang;
  recall: Promise<string[]>;
  injecting?: boolean;
}

interface OpenConversation {
  id: string;
  call: CallRecord;
}

export interface ElevenLabsMemory {
  begin: (persona: string | undefined, lang: Lang) => string;
  connected: (conversationId: string, send: (text: string) => void) => void;
  ended: () => void;
}

export function useElevenLabsMemory(): ElevenLabsMemory {
  const attemptRef = useRef(0);
  /** The call armed by the latest begin(); recall is injected only into it. */
  const callRef = useRef<CallRecord | null>(null);
  /** Connected conversations not yet disconnected, oldest first. */
  const openRef = useRef<OpenConversation[]>([]);
  const ingestedRef = useRef(new Set<string>());

  const begin = useCallback((persona: string | undefined, lang: Lang) => {
    const userId = getMemoryUserId();
    callRef.current = {
      attempt: ++attemptRef.current,
      userId,
      persona,
      lang,
      recall: recallMemories(userId),
    };
    return userId;
  }, []);

  const connected = useCallback((conversationId: string, send: (text: string) => void) => {
    const call = callRef.current;
    if (!call) return;
    openRef.current.push({ id: conversationId, call });
    if (call.injecting) return;
    call.injecting = true;
    const { attempt } = call;
    void call.recall.then((memories) => {
      if (attemptRef.current !== attempt || callRef.current !== call) return;
      const text = formatMemoryUpdate(memories, call.lang);
      if (!text) return;
      try {
        send(text);
      } catch {
        // The call ended between recall and send; nothing to inject.
      }
    });
  }, []);

  const ended = useCallback(() => {
    const open = openRef.current.shift();
    if (!open) return;
    // A recall still in flight for this call has nothing left to reach.
    if (callRef.current === open.call) callRef.current = null;
    if (ingestedRef.current.has(open.id)) return;
    ingestedRef.current.add(open.id);
    ingestConversation({
      userId: open.call.userId,
      conversationId: open.id,
      persona: open.call.persona,
      lang: open.call.lang,
    });
  }, []);

  return useMemo(() => ({ begin, connected, ended }), [begin, connected, ended]);
}

