import { afterEach, describe, expect, test } from "bun:test";
import { MemoryCallLifecycle } from "/Users/jessearmand/Develop/realtime-persona/lib/memory/call-lifecycle";
import { listRecentMemories } from "/Users/jessearmand/Develop/realtime-persona/lib/memory/mem0-rest";

const tick = () => new Promise((r) => setTimeout(r, 0));

function harness() {
  const ingested: string[] = [];
  const recalls: Array<(m: string[]) => void> = [];
  const life = new MemoryCallLifecycle({
    userId: () => "tsubaki-u",
    recall: () => new Promise<string[]>((r) => recalls.push(r)),
    format: (m, lang) => `${lang}:${m.join(",")}`,
    ingest: (t) => ingested.push(`${t.conversationId}/${t.lang}`),
  });
  return { life, ingested, recalls };
}

describe("MemoryCallLifecycle", () => {
  test("normal call: inject once, ingest once", async () => {
    const { life, ingested, recalls } = harness();
    const sent: string[] = [];
    life.begin("vesper", "en");
    life.connected("c1", (t) => sent.push(t));
    recalls[0](["Ren plays cello"]);
    await tick();
    life.ended();
    life.ended();
    expect(sent).toEqual(["en:Ren plays cello"]);
    expect(ingested).toEqual(["c1/en"]);
  });

  test("restart: late old disconnect before new connect", async () => {
    const { life, ingested, recalls } = harness();
    const sent: string[] = [];
    life.begin("vesper", "en");
    life.connected("c1", (t) => sent.push(`s1 ${t}`));
    recalls[0](["fact"]);
    await tick();
    life.begin("vesper", "ja"); // language change re-arms first
    life.ended(); // old session's onDisconnect lands late
    life.connected("c2", (t) => sent.push(`s2 ${t}`));
    recalls[1](["fact"]);
    await tick();
    life.ended();
    expect(ingested).toEqual(["c1/en", "c2/ja"]);
    expect(sent).toEqual(["s1 en:fact", "s2 ja:fact"]);
  });

  test("restart: late old disconnect after new connect", async () => {
    const { life, ingested, recalls } = harness();
    const sent: string[] = [];
    life.begin("vesper", "en");
    life.connected("c1", () => {});
    life.begin("vesper", "ja");
    life.connected("c2", (t) => sent.push(t));
    life.ended(); // c1's disconnect, after c2 is up
    recalls[1](["fact"]);
    await tick();
    expect(sent).toEqual(["ja:fact"]); // the new call still gets its memories
    life.ended();
    expect(ingested).toEqual(["c1/en", "c2/ja"]);
  });

  test("a replaced call's slow recall never reaches the new call", async () => {
    const { life, recalls } = harness();
    const sent: string[] = [];
    life.begin("vesper", "en");
    life.connected("c1", (t) => sent.push(`s1 ${t}`));
    life.begin("vesper", "ja");
    recalls[0](["stale"]);
    await tick();
    expect(sent).toEqual([]);
  });

  test("disconnect with nothing open is a no-op", () => {
    const { life, ingested } = harness();
    life.begin("vesper", "en");
    life.ended();
    expect(ingested).toEqual([]);
  });
});

describe("listRecentMemories pagination", () => {
  const realFetch = globalThis.fetch;
  afterEach(() => {
    globalThis.fetch = realFetch;
  });

  test("reads every page, then returns the newest first", async () => {
    const pages: Record<number, unknown> = {
      1: { results: [{ id: "a", memory: "old", updated_at: "2026-01-01T00:00:00Z" }], next: "p2" },
      2: { results: [{ id: "b", memory: "mid", updated_at: "2026-06-01T00:00:00Z" }], next: "p3" },
      3: { results: [{ id: "c", memory: "new", updated_at: "2026-11-01T00:00:00Z" }], next: null },
    };
    const requested: number[] = [];
    globalThis.fetch = (async (url: string) => {
      const page = Number(new URL(url).searchParams.get("page"));
      requested.push(page);
      return new Response(JSON.stringify(pages[page]), { status: 200 });
    }) as typeof fetch;
    const out = await listRecentMemories("k", "tsubaki-u", 2);
    expect(requested).toEqual([1, 2, 3]);
    expect(out.map((m) => m.memory)).toEqual(["new", "mid"]);
  });

  test("stops at the page cap", async () => {
    let calls = 0;
    globalThis.fetch = (async () => {
      calls++;
      return new Response(JSON.stringify({ results: [{ id: `${calls}`, memory: "m" }], next: "more" }));
    }) as typeof fetch;
    await listRecentMemories("k", "tsubaki-u", 5);
    expect(calls).toBe(10);
  });
});

